export const RECOGNIZING_PROBLEMS_ACTIVITIES = [
{n:1,type:"mcq",micro:"Apa itu masalah",q:"Manakah yang paling tepat menggambarkan sebuah 'masalah'?",options:["Keadaan di mana ada jarak antara situasi sekarang dan situasi yang kita inginkan","Keadaan ketika segalanya sudah lancar dan kita merasa tidak perlu mengubah keadaan","Sesuatu yang hanya dialami orang dewasa di tempat kerja, bukan oleh anak sekolah"],answer:0,explain:"Masalah muncul ketika ada perbedaan antara keadaan sekarang dan keadaan yang kita inginkan, dan ada hambatan di antaranya.",hint:"Pikirkan tentang 'di mana aku sekarang' dibandingkan 'di mana aku ingin berada'."},
{n:2,type:"mcq",micro:"Mengenali masalah sehari-hari",q:"Tasya ingin berangkat sekolah, tetapi ban sepedanya kempes. Apa masalahnya?",options:["Sepeda Tasya berwarna merah dan dibeli tahun lalu","Ban sepeda kempes sehingga Tasya sulit berangkat sekolah","Sepeda Tasya berwarna biru dan sudah dipakai dua tahun"],answer:1,explain:"Masalahnya adalah hambatan (ban kempes) yang menghalangi tujuan Tasya (berangkat sekolah).",hint:"Cari hal yang menghalangi Tasya mencapai tujuannya."},
{n:3,type:"tf",micro:"Masalah butuh tujuan",q:"Benar atau Salah: Sesuatu baru bisa disebut masalah jika ada sesuatu yang ingin kita capai atau ubah.",answer:true,explain:"Tanpa tujuan atau keinginan, tidak ada 'jarak' yang perlu ditutup, jadi tidak ada masalah untuk dipecahkan.",hint:"Bisakah ada masalah kalau kamu tidak menginginkan apa pun berubah?"},
{n:4,type:"mcq",micro:"Masalah vs bukan masalah",q:"Manakah yang BUKAN sebuah masalah?",options:["Pensilmu patah tepat saat ulangan dimulai","Kamu lupa membawa bekal dan sekarang lapar","Langit berwarna biru pada siang hari yang cerah"],answer:2,explain:"Langit biru adalah keadaan biasa yang tidak menghalangi tujuan siapa pun; dua pilihan lainnya menghambat sesuatu yang ingin dicapai.",hint:"Mana yang tidak menghalangi seseorang melakukan atau mendapatkan sesuatu?"},
{n:5,type:"mcq",micro:"Perasaan sebagai tanda",q:"Rina merasa bingung dan kesal setiap kali membuka buku matematikanya. Perasaan ini bisa menjadi tanda bahwa...",options:["Ada masalah yang perlu dikenali, misalnya ada bagian yang belum ia pahami","Matematika tidak berguna bagi hidup, jadi perasaan itu cukup dibiarkan saja","Rina sebaiknya berganti buku baru, sebab rasa kesal itu berasal dari sampulnya"],answer:0,explain:"Perasaan tidak nyaman sering menjadi sinyal awal bahwa ada masalah yang belum kita namai dengan jelas.",hint:"Rasa kesal atau bingung biasanya menunjuk ke arah sesuatu yang perlu diperbaiki."},
{n:6,type:"mcq",micro:"Kapan sesuatu jadi masalah",q:"Hujan turun deras. Bagi seorang petani yang sawahnya kering, hujan itu...",options:["Merusak tanaman dan merugikan petani","Bisa jadi bukan masalah, malah membantu","Tidak berpengaruh pada tanaman di sawah"],answer:1,explain:"Apakah sesuatu menjadi masalah bergantung pada tujuan orang tersebut. Hujan membantu petani yang butuh air.",hint:"Pikirkan apakah hujan menghalangi atau membantu tujuan si petani."},
{n:7,type:"mcq",micro:"Kapan sesuatu jadi masalah",q:"Hujan deras yang sama turun saat kamu ingin bermain sepak bola di lapangan terbuka. Bagi kamu, hujan itu...",options:["Bukan masalah, sebab hujan deras cocok untuk bermain bola","Menguntungkan karena lapangan menjadi kering dan nyaman","Menjadi masalah karena menghalangi rencanamu bermain"],answer:2,explain:"Kejadian yang sama (hujan) bisa menjadi masalah bagi satu orang dan bukan masalah bagi orang lain, tergantung tujuannya.",hint:"Apakah hujan menghalangi hal yang ingin kamu lakukan?"},
{n:8,type:"order",micro:"Langkah mengenali masalah",q:"Urutkan langkah-langkah paling awal untuk mengenali sebuah masalah.",items:["Menyadari ada rasa tidak nyaman atau sesuatu yang tidak beres","Menyebutkan dengan kata-kata apa yang sedang terjadi","Membandingkan keadaan sekarang dengan keadaan yang diinginkan"],answer:[0,1,2],explain:"Biasanya kita mulai dengan merasakan ada yang tidak beres, lalu menamainya, lalu membandingkannya dengan keadaan ideal.",hint:"Perasaan datang lebih dulu, kata-kata menyusul, lalu perbandingan."},
{n:9,type:"mcq",micro:"Masalah orang lain",q:"Adik kelasmu menangis karena tidak menemukan kelasnya di hari pertama sekolah. Masalah ini...",options:["Adalah masalah nyata bagi adik kelas itu, meski bukan kamu yang mengalaminya","Baru menjadi masalah setelah gurunya sendiri menyatakan bahwa itu adalah masalah","Bukan masalah karena kamu tidak mengalaminya, jadi sebaiknya dibiarkan saja"],answer:0,explain:"Sebuah masalah tetap nyata bagi orang yang mengalaminya, walaupun kita sendiri tidak merasakannya.",hint:"Apakah anak itu terhalang mencapai sesuatu yang ia inginkan?"},
{n:10,type:"mcq",micro:"Masalah vs keinginan biasa",q:"Kamu ingin punya sepatu baru berwarna merah, padahal sepatumu sekarang masih bagus dan nyaman. Ini lebih tepat disebut...",options:["Masalah mendesak yang harus segera dipecahkan karena sepatu lamamu sudah rusak","Sebuah keinginan, bukan masalah, karena tidak ada yang benar-benar terhambat","Sebuah kewajiban yang harus dipenuhi hari ini, bukan keinginan maupun masalah"],answer:1,explain:"Kalau tidak ada tujuan yang terhalang (sepatu lama masih berfungsi), itu keinginan biasa, bukan masalah yang harus dipecahkan.",hint:"Apakah ada sesuatu yang tidak bisa kamu lakukan tanpa sepatu baru itu?"},
{n:11,type:"mcq",micro:"Tanda adanya masalah",q:"Manakah yang paling mungkin menjadi tanda bahwa sebuah kelompok punya masalah?",options:["Semua anggota tersenyum dan saling membantu","Tugas kelompok selesai tepat waktu dan semua anggota puas","Beberapa anggota terus mengeluh dan pekerjaan tidak maju-maju"],answer:2,explain:"Keluhan yang berulang dan pekerjaan yang macet adalah tanda umum adanya masalah yang belum dikenali.",hint:"Cari tanda 'sesuatu tidak berjalan seperti yang diharapkan'."},
{n:12,type:"tf",micro:"Masalah tidak selalu buruk",q:"Benar atau Salah: Mengenali sebuah masalah selalu berarti kabar buruk dan sebaiknya dihindari.",answer:false,explain:"Mengenali masalah lebih awal justru membantu kita memperbaikinya sebelum menjadi besar. Masalah adalah kesempatan untuk membuat sesuatu lebih baik.",hint:"Apakah lebih baik tahu ban kempes sekarang atau saat sudah di tengah jalan?"},
{n:13,type:"mcq",micro:"Masalah tersembunyi",q:"Nilai ulangan Beni tiba-tiba turun. Ibu Beni berkata 'Beni malas.' Apa yang mungkin terlewat?",options:["Bisa jadi ada masalah lain, misalnya Beni kurang tidur, tidak paham materi, atau sedang sedih","Nilai turun itu bukan masalah, sebab nilai ulangan memang naik turun tanpa sebab yang jelas","Penyebabnya hanya satu, yaitu Beni memang pemalas, jadi tidak ada hal lain yang perlu dicari"],answer:0,explain:"Menyimpulkan penyebab terlalu cepat bisa membuat kita melewatkan masalah yang sebenarnya.",hint:"Apakah 'malas' satu-satunya kemungkinan alasan nilai turun?"},
{n:14,type:"mcq",micro:"Masalah butuh diselesaikan atau diterima",q:"Kamu ingin lompatanmu setinggi lompatan atlet dewasa dalam satu minggu. Ini adalah...",options:["Masalah biasa yang bisa langsung dipecahkan dalam satu minggu dengan latihan sedikit saja","Harapan yang tidak realistis untuk waktu sesingkat itu, jadi tujuannya perlu disesuaikan","Bukan masalah maupun harapan, karena lompatan atlet dewasa bisa ditiru anak kapan saja"],answer:1,explain:"Kadang 'masalah' muncul karena tujuannya sendiri tidak masuk akal. Menyesuaikan tujuan bisa jadi bagian dari pemecahan.",hint:"Apakah masalahnya pada kemampuanmu, atau pada tujuan yang terlalu tinggi untuk satu minggu?"},
{n:15,type:"mcq",micro:"Mengenali masalah dari data kecil",q:"Setiap hari Jumat, kelasmu selalu terlambat masuk setelah istirahat. Hari lain tidak. Ini menunjukkan...",options:["Semua hari sama, jadi keterlambatan hari Jumat tidak perlu diselidiki","Hanya kebetulan semata, yang tidak mungkin punya sebab tertentu","Ada pola yang mengarah ke sebuah masalah khusus di hari Jumat"],answer:2,explain:"Pola yang berulang (selalu di hari Jumat) adalah petunjuk kuat bahwa ada masalah tertentu yang khas hari itu.",hint:"Kalau sesuatu terjadi berulang di waktu yang sama, itu biasanya bukan kebetulan."},
{n:16,type:"mcq",micro:"Masalah vs gejala",q:"Lampu di kamarmu berkedip-kedip. Kamu terus mengetuk lampunya supaya menyala normal. Apa yang mungkin kamu lewatkan?",options:["Kedipan itu mungkin hanya gejala; masalah sebenarnya bisa pada kabel atau sakelar","Lampu berkedip itu hal biasa, jadi penyebabnya tidak perlu dicari dan dibiarkan saja","Mengetuk lampu sudah cara terbaik dan teraman, jadi penyebab lain tidak perlu dicari"],answer:0,explain:"Menangani gejala (kedipan) tanpa mencari penyebabnya sering membuat masalah kembali lagi.",hint:"Apakah lampu berkedip itu penyebab, atau tanda dari sesuatu yang lebih dalam?"},
{n:17,type:"tf",micro:"Orang bisa melihat masalah yang sama secara berbeda",q:"Benar atau Salah: Jika sebuah situasi benar-benar merupakan masalah, maka semua orang pasti sepakat bahwa itu masalah.",answer:false,explain:"Tidak selalu. Karena masalah bergantung pada tujuan dan nilai masing-masing orang, situasi yang sama bisa dianggap masalah oleh satu orang dan bukan masalah oleh yang lain — seperti hujan bagi petani dan bagi pemain bola.",hint:"Ingat contoh hujan bagi petani dan bagi pemain bola."},
{n:18,type:"mcq",micro:"Menunda mengenali masalah",q:"Apa risiko paling umum kalau kita menunda-nunda mengakui bahwa ada masalah?",options:["Masalahnya biasanya hilang sendiri tanpa perlu diurus","Masalah kecil bisa membesar dan lebih sulit diperbaiki","Justru membuat masalah menjadi lebih ringan dan mudah"],answer:1,explain:"Banyak masalah tumbuh seiring waktu; mengenalinya lebih awal biasanya membuatnya lebih mudah diatasi.",hint:"Pikirkan lubang kecil di atap saat musim hujan tiba."},
{n:19,type:"mcq",micro:"Mengenali masalah, belum menyelesaikan",q:"Langkah 'mengenali masalah' berbeda dari 'menyelesaikan masalah' karena mengenali berarti...",options:["Melupakan masalah itu agar pikiran kita menjadi tenang kembali","Langsung memberi jawaban akhir tanpa memahami masalahnya lebih dulu","Menyadari dan menyatakan bahwa ada masalah serta apa masalahnya"],answer:2,explain:"Mengenali masalah adalah tahap menyadari dan menamai; menyelesaikan datang setelahnya.",hint:"Kamu belum mencari solusi di tahap ini — kamu baru menunjuk masalahnya."},
{n:20,type:"open",micro:"Menemukan masalah di sekitar",q:"Sebutkan satu masalah kecil yang kamu perhatikan di rumah atau sekolah minggu ini, dan jelaskan mengapa itu kamu sebut masalah.",explain:"Jawaban yang baik menyebutkan keadaan sekarang, tujuan yang terhalang, dan hambatannya.",hint:"Pola: 'Keadaan sekarang ... padahal aku/kita ingin ... hambatannya adalah ...'",sample:"Contoh: 'Rak sepatu di depan kelas selalu berantakan sehingga sepatu sering hilang atau tertukar. Ini masalah karena tujuannya (menemukan sepatu sendiri dengan cepat) terhalang oleh keadaan rak yang tidak teratur.'"},
{n:21,type:"mcq",micro:"Menggambarkan masalah dengan jelas",q:"Manakah pernyataan masalah yang paling jelas?",options:["Buku di perpustakaan sekolah tidak tersusun berdasarkan topik, sehingga siswa butuh waktu lama untuk menemukan buku yang dicari","Perpustakaan sekolah kami menyebalkan dan membuat banyak siswa merasa malas serta tidak betah berada di dalamnya","Sekolah harus segera membeli lebih banyak buku dan rak baru untuk perpustakaan supaya semua siswa senang membaca"],answer:0,explain:"Pernyataan yang jelas menyebutkan apa yang terjadi, di mana, dan akibatnya, tanpa hanya melampiaskan perasaan.",hint:"Cari pernyataan yang bisa langsung dipahami orang lain tanpa bertanya lagi."},
{n:22,type:"mcq",micro:"Masalah vs gejala",q:"Gejala: 'Aku sering pusing di kelas.' Manakah yang mungkin merupakan masalah di baliknya?",options:["Pusing itu sendiri sudah masalahnya, tak perlu cari penyebab","Ruang kelas panas dan pengap sehingga sulit berkonsentrasi","Kamu menderita sakit berat sehingga perlu segera dirawat inap"],answer:1,explain:"Gejala adalah tanda yang terasa; masalah adalah penyebab yang menghasilkan tanda itu. Ruangan pengap bisa jadi penyebabnya.",hint:"Tanya: 'Apa yang membuat gejala ini muncul?'"},
{n:23,type:"mcq",micro:"Siapa yang punya masalah",q:"'Kakak selalu memakai meja belajar saat aku butuh.' Siapa yang mengalami masalah di sini?",options:["Meja belajar, karena meja itu dipakai terlalu sering oleh orang lain","Kakak, karena ia harus berbagi meja dengan adiknya yang mengganggu","Kamu, karena kamu terhalang menggunakan meja saat membutuhkannya"],answer:2,explain:"Orang yang tujuannya terhalang adalah pemilik masalah. Di sini, kamu yang tidak bisa memakai meja.",hint:"Siapa yang tidak bisa melakukan hal yang ingin dilakukannya?"},
{n:24,type:"mcq",micro:"Kapan masalah terjadi",q:"Mengetahui KAPAN sebuah masalah muncul berguna karena...",options:["Membantu mempersempit kemungkinan penyebabnya","Langsung memberi solusi tanpa perlu cari penyebab","Tidak berguna karena waktunya tak terkait penyebab"],answer:0,explain:"Waktu kejadian sering menunjuk ke penyebab: 'hanya saat hujan', 'hanya pagi hari', 'hanya setelah update'.",hint:"Kalau sesuatu hanya rusak di waktu tertentu, apa artinya soal penyebabnya?"},
{n:25,type:"mcq",micro:"Di mana masalah terjadi",q:"Wifi di rumah lancar di ruang tamu tetapi putus-putus di kamar belakang. Informasi 'di mana' ini menunjukkan...",options:["Kamar belakang tidak butuh wifi, jadi sinyal yang putus tak perlu dipikirkan","Masalahnya kemungkinan terkait jarak atau penghalang dari sumber wifi","Wifi di rumah itu rusak di semua ruangan, termasuk ruang tamu"],answer:1,explain:"Perbedaan berdasarkan lokasi adalah petunjuk penting tentang penyebab masalah teknis.",hint:"Apa bedanya ruang tamu dan kamar belakang dari sisi sinyal?"},
{n:26,type:"classify",micro:"Masalah, gejala, atau solusi",q:"Kelompokkan tiap pernyataan sebagai 'Gejala (tanda yang terasa)', 'Masalah (penyebab)', atau 'Solusi (usulan tindakan)'.",items:["Tanamanku layu setiap sore","Pot tanaman tidak punya lubang sehingga air menggenang dan akar busuk","Buat lubang kecil di dasar pot","Daun menguning di bagian bawah"],groups:["Gejala","Masalah","Solusi"],answer:{"Gejala":["Tanamanku layu setiap sore","Daun menguning di bagian bawah"],"Masalah":["Pot tanaman tidak punya lubang sehingga air menggenang dan akar busuk"],"Solusi":["Buat lubang kecil di dasar pot"]},explain:"Gejala adalah tanda yang kita lihat/rasa, masalah adalah penyebabnya, solusi adalah tindakan yang diusulkan.",hint:"Tanya untuk tiap item: apakah ini yang kulihat, kenapa itu terjadi, atau apa yang harus kulakukan?"},
{n:27,type:"tf",micro:"Menyalahkan orang bukan mendefinisikan masalah",q:"Benar atau Salah: 'Semua ini gara-gara Doni' adalah cara yang baik untuk mendefinisikan sebuah masalah.",answer:false,explain:"Menyalahkan orang menutup penyelidikan dan sering tidak akurat. Definisi yang baik menjelaskan apa yang terjadi dan akibatnya, bukan mencari kambing hitam.",hint:"Apakah kalimat itu membantu kita memahami apa yang sebenarnya terjadi?"},
{n:28,type:"mcq",micro:"Fakta vs perasaan dalam menggambarkan masalah",q:"Manakah yang merupakan FAKTA tentang masalah, bukan sekadar perasaan?",options:["Banyak siswa di sekolah tidak menyukai jadwal ini dan ingin jadwalnya diganti","Jadwal piket ini tidak adil dan dibuat khusus untuk merugikan kelompokku","Dalam 3 minggu terakhir, 4 dari 6 hari piket jatuh pada kelompokku"],answer:2,explain:"Fakta bisa diperiksa dan dihitung; 'tidak adil' dan 'semua membenci' adalah penilaian atau perasaan.",hint:"Mana yang bisa kamu buktikan dengan menghitung atau mencatat?"},
{n:29,type:"mcq",micro:"Ukuran masalah",q:"Mengapa berguna mengetahui SEBERAPA SERING atau SEBERAPA BESAR sebuah masalah terjadi?",options:["Supaya kita bisa menilai apakah masalah itu layak diprioritaskan dan melihat apakah solusi berhasil","Ukuran dan frekuensi masalah tidak penting, karena semua masalah harus diperlakukan dengan cara yang sama","Supaya kita bisa mengabaikannya dengan alasan yang terdengar ilmiah dan tidak perlu bertindak"],answer:0,explain:"Mengukur masalah membantu kita memutuskan prioritas dan nanti mengecek apakah keadaan membaik.",hint:"Bagaimana kamu tahu solusimu berhasil kalau kamu tidak tahu keadaan awalnya?"},
{n:30,type:"order",micro:"Menyusun gambaran masalah",q:"Urutkan pertanyaan-pertanyaan ini untuk menyusun gambaran masalah yang lengkap.",items:["Apa yang terjadi (apa gejalanya)?","Siapa yang terpengaruh dan seberapa sering?","Apa akibatnya jika dibiarkan?"],answer:[0,1,2],explain:"Mulai dari apa yang terjadi, lalu siapa dan seberapa sering, lalu akibatnya — ini membentuk gambaran utuh.",hint:"Deskripsi datang dulu, dampak belakangan."},
{n:31,type:"mcq",micro:"Masalah yang terlalu samar",q:"'Sekolah harus lebih baik' terlalu samar untuk dipecahkan karena...",options:["Kalimatnya terlalu panjang sehingga siswa sulit membacanya dalam sekali lihat","Tidak menyebutkan apa tepatnya yang kurang baik, bagi siapa, dan di bagian mana","Kalimat itu sudah sangat jelas dan bisa langsung dikerjakan oleh semua pihak"],answer:1,explain:"Masalah yang bisa dipecahkan harus cukup spesifik: apa, di mana, bagi siapa, dan seberapa besar.",hint:"Apa yang harus ditambahkan supaya orang tahu harus mulai dari mana?"},
{n:32,type:"mcq",micro:"Masalah yang terlalu sempit",q:"Sebaliknya, mendefinisikan masalah terlalu sempit — misalnya 'pintu kelas 3B macet' padahal SEMUA pintu di lantai itu macet — berisiko...",options:["Tidak ada risiko, karena masalah yang lebih sempit lebih mudah dan cepat diselesaikan","Membuat masalah terasa terlalu besar dan luas sehingga orang enggan memulai perbaikan","Membuat kita hanya memperbaiki satu bagian kecil dan melewatkan masalah yang lebih luas"],answer:2,explain:"Definisi yang terlalu sempit bisa menyembunyikan pola yang lebih besar dan membuat solusi tidak menyeluruh.",hint:"Kalau semua pintu bermasalah, apakah cukup memperbaiki satu saja?"},
{n:33,type:"tf",micro:"Menggambar atau memetakan masalah",q:"Benar atau Salah: Menggambar diagram atau membuat daftar bagian-bagian masalah bisa membantu kita melihatnya lebih jelas.",answer:true,explain:"Memvisualkan masalah — lewat diagram, peta, atau daftar — sering memunculkan hubungan dan penyebab yang tidak terlihat saat hanya dipikirkan.",hint:"Apakah lebih mudah memahami rute perjalanan lewat peta atau lewat hafalan?"},
{n:34,type:"mcq",micro:"Bahasa netral",q:"Ubah 'Guru itu payah menjelaskan' menjadi pernyataan masalah yang lebih netral dan berguna.",options:["Saat materi pecahan dijelaskan minggu lalu, sebagian besar kelas masih bingung setelahnya, terlihat dari nilai kuis yang rendah","Aku tidak suka pelajaran ini karena menurutku guru terlalu cepat dan membosankan, jadi kurasa teman-teman sekelas ikut merasa begitu","Guru itu tidak becus mengajar pecahan, sehingga seluruh kelas bingung dan nilai kuis kami jadi rendah karena kesalahannya"],answer:0,explain:"Pernyataan netral fokus pada apa yang terjadi dan buktinya, bukan pada penilaian terhadap orang.",hint:"Sebutkan apa yang terjadi dan bagaimana kamu tahu itu terjadi."},
{n:35,type:"mcq",micro:"Memisahkan beberapa masalah",q:"'Aku tidak bisa mengerjakan PR karena tidak punya buku, lampu belajarku mati, dan aku juga tidak paham soalnya.' Berapa masalah yang sebenarnya disebut di sini?",options:["Satu masalah besar yang tidak bisa dipisah-pisahkan","Tiga masalah berbeda yang masing-masing bisa ditangani","Dua masalah saja, sebab lampu mati bukan masalah belajar"],answer:1,explain:"Sering satu keluhan berisi beberapa masalah. Memisahkannya membuat tiap bagian lebih mudah diselesaikan.",hint:"Hitung berapa hambatan berbeda yang disebut."},
{n:36,type:"mcq",micro:"Konteks masalah",q:"Sebelum menyebut 'komputer lab selalu lambat' sebagai masalah, informasi tambahan mana yang paling berguna?",options:["Nama merek keyboard dan tahun pembelian komputer lab","Warna casing dan ukuran meja tempat komputer diletakkan","Sejak kapan mulai lambat, dan lambat saat menjalankan apa"],answer:2,explain:"Kapan mulai dan dalam kondisi apa adalah konteks yang mempersempit penyebab.",hint:"Detail mana yang membantu menebak penyebabnya?"},
{n:37,type:"tf",micro:"Masalah bisa berubah saat dipahami lebih dalam",q:"Benar atau Salah: Setelah kita menyelidiki, pemahaman kita tentang apa masalah sebenarnya boleh berubah.",answer:true,explain:"Definisi masalah bukan sesuatu yang beku. Semakin banyak yang kita ketahui, semakin tepat kita bisa merumuskannya.",hint:"Apakah tebakan pertama selalu tebakan terbaik?"},
{n:38,type:"mcq",micro:"Masalah vs tugas biasa",q:"Manakah ini: 'Menyapu lantai kelas setiap sore' bagi petugas piket yang punya sapu dan waktu?",options:["Tugas rutin biasa, bukan masalah, karena caranya sudah jelas dan tidak ada hambatan berarti","Bukan tugas maupun masalah, karena kegiatan itu sebenarnya tidak perlu dilakukan oleh petugas","Sebuah masalah besar, karena menyapu lantai setiap sore menghambat petugas piket yang bersangkutan"],answer:0,explain:"Kalau cara dan alatnya jelas serta tidak ada hambatan, itu tugas rutin, bukan masalah yang perlu dipecahkan.",hint:"Adakah hambatan yang membuat tugas ini sulit diselesaikan?"},
{n:39,type:"mcq",micro:"Menuliskan dampak",q:"Pernyataan masalah yang menyebutkan dampak ('...sehingga 10 siswa terlambat setiap hari') lebih berguna daripada yang tidak, karena...",options:["Membuat kalimat masalah menjadi lebih panjang dan terlihat rumit","Membantu orang lain memahami mengapa masalah ini penting untuk ditangani","Membuat masalah terdengar lebih dramatis dan menakutkan bagi pembaca"],answer:1,explain:"Menyebut dampak membantu menilai seberapa penting masalah itu dibanding masalah lain.",hint:"Mengapa seseorang harus peduli pada masalah ini?"},
{n:40,type:"open",micro:"Menulis pernyataan masalah yang jelas",q:"Ubah keluhan samar ini menjadi pernyataan masalah yang jelas: 'Kantin selalu ribet.'",explain:"Pernyataan yang baik menjawab: apa yang terjadi, kapan/di mana, kemungkinan sebab, dan dampaknya.",hint:"Ganti kata 'ribet' dengan gambaran konkret yang bisa diperiksa.",sample:"Contoh: 'Pada jam istirahat pertama, antrean di kantin bisa mencapai 20 menit karena hanya ada satu kasir, sehingga banyak siswa tidak sempat makan sebelum bel masuk.' Menyebut kapan, mengapa (satu kasir), dan dampaknya."},
{n:41,type:"mcq",micro:"Struktur pernyataan masalah",q:"Kerangka pernyataan masalah yang umum adalah: 'Saat ini [keadaan sekarang], padahal [keadaan yang diinginkan], karena [hambatan], sehingga [dampak].' Bagian mana yang menyatakan tujuan?",options:["Hambatan","Keadaan sekarang","Keadaan yang diinginkan"],answer:2,explain:"'Keadaan yang diinginkan' adalah tujuan — ke mana kita ingin sampai.",hint:"Bagian mana yang menggambarkan 'seharusnya seperti apa'?"},
{n:42,type:"mcq",micro:"Akar masalah",q:"'Akar masalah' berarti...",options:["Penyebab paling mendasar yang, jika diperbaiki, membuat gejala-gejala ikut hilang","Masalah pertama yang kita lihat atau kita rasakan, meskipun itu hanya salah satu gejalanya","Masalah yang paling menyebalkan dan paling membuat kita marah dibandingkan masalah-masalah lainnya"],answer:0,explain:"Akar masalah adalah sumber sesungguhnya; menanganinya mencegah masalah muncul lagi.",hint:"Kalau ini diperbaiki, apakah gejala lain ikut hilang?"},
{n:43,type:"order",micro:"Teknik 5 Mengapa",q:"Urutkan penerapan teknik '5 Mengapa' pada masalah 'Aku terlambat sekolah'.",items:["Mengapa terlambat? Karena bangun kesiangan.","Mengapa bangun kesiangan? Karena alarm tidak berbunyi.","Mengapa alarm tidak berbunyi? Karena ponsel mati semalam.","Mengapa ponsel mati? Karena lupa mengisi daya — ini akar yang bisa diperbaiki."],answer:[0,1,2,3],explain:"Dengan terus bertanya 'mengapa', kita bergerak dari gejala (terlambat) ke akar (lupa mengisi daya ponsel).",hint:"Tiap jawaban menjadi bahan pertanyaan 'mengapa' berikutnya."},
{n:44,type:"mcq",micro:"5 Mengapa",q:"Tujuan utama teknik '5 Mengapa' adalah...",options:["Menyalahkan lima orang berbeda satu per satu supaya jelas siapa yang paling bertanggung jawab","Menembus dari gejala ke penyebab yang lebih dalam dengan bertanya 'mengapa' berulang kali","Membuat masalah terdengar rumit sehingga orang lain tidak berani lagi bertanya soal masalah itu"],answer:1,explain:"Setiap 'mengapa' membawa kita satu lapis lebih dekat ke akar masalah.",hint:"Angka 5 hanya kira-kira — intinya terus menggali."},
{n:45,type:"mcq",micro:"Fakta vs asumsi",q:"'Pengunjung web kita sedikit. Pasti karena desainnya jelek.' Bagian 'pasti karena desainnya jelek' adalah...",options:["Tidak keduanya","Fakta yang sudah terbukti","Asumsi yang belum diperiksa"],answer:2,explain:"Itu dugaan tentang penyebab. Bisa jadi benar, tapi belum diuji dengan data.",hint:"Apakah ada bukti langsung, atau baru tebakan?"},
{n:46,type:"mcq",micro:"Menguji asumsi",q:"Cara terbaik menangani asumsi 'orang tidak datang karena desainnya jelek' adalah...",options:["Mencari data: tanya beberapa pengunjung, cek dari mana mereka berhenti, bandingkan dengan kemungkinan lain","Mengabaikannya, karena asumsi biasanya benar dan tidak perlu diperiksa dengan bertanya ke orang lain","Langsung merombak seluruh desain supaya lebih bagus menurut selera tim pembuatnya sendiri"],answer:0,explain:"Asumsi sebaiknya diubah menjadi pertanyaan yang bisa diuji sebelum kita bertindak besar.",hint:"Bagaimana kamu bisa tahu apakah asumsi itu benar sebelum menghabiskan banyak usaha?"},
{n:47,type:"mcq",micro:"Kriteria keberhasilan",q:"'Kriteria' sebuah solusi masalah adalah...",options:["Daftar orang yang terlibat dalam masalah beserta tugas masing-masing","Syarat-syarat yang harus dipenuhi agar solusi dianggap berhasil","Nama lain untuk masalah itu sendiri, yaitu keadaan yang ingin diubah"],answer:1,explain:"Kriteria adalah tolok ukur: misalnya 'antrean di bawah 5 menit' atau 'biaya di bawah Rp50.000'.",hint:"Bagaimana nanti kita menilai solusi ini cukup baik atau tidak?"},
{n:48,type:"mcq",micro:"Batasan",q:"'Batasan' (kendala) dalam sebuah masalah adalah...",options:["Ide-ide solusi yang dikumpulkan lewat diskusi kelompok sebelum masalah itu dirumuskan","Perasaan kita tentang masalah itu, yang dicatat untuk menentukan seberapa penting masalahnya","Hal-hal yang tidak bisa kita ubah dan harus kita patuhi, seperti anggaran, waktu, atau aturan"],answer:2,explain:"Batasan membatasi ruang solusi: waktu tersedia, uang, bahan, aturan sekolah, dan sebagainya.",hint:"Apa yang membuat beberapa solusi tidak mungkin dilakukan?"},
{n:49,type:"classify",micro:"Kriteria vs batasan",q:"Untuk masalah 'merancang taman baca kelas', kelompokkan tiap poin sebagai 'Kriteria (tanda berhasil)' atau 'Batasan (kendala tetap)'.",items:["Setiap siswa bisa menemukan buku dalam 1 menit","Anggaran maksimal Rp200.000","Harus muat di sudut kelas berukuran 2x2 meter","Minimal 80% siswa merasa nyaman membaca di sana"],groups:["Kriteria","Batasan"],answer:{"Kriteria":["Setiap siswa bisa menemukan buku dalam 1 menit","Minimal 80% siswa merasa nyaman membaca di sana"],"Batasan":["Anggaran maksimal Rp200.000","Harus muat di sudut kelas berukuran 2x2 meter"]},explain:"Kriteria mengukur keberhasilan; batasan adalah kondisi tetap yang membatasi pilihan solusi.",hint:"Tanya: apakah poin ini 'tanda sukses' atau 'aturan main yang tak bisa diubah'?"},
{n:50,type:"mcq",micro:"Masalah yang bisa ditindaklanjuti",q:"Manakah rumusan masalah yang paling bisa ditindaklanjuti?",options:["Di kelas kami, siswa yang duduk di barisan belakang sulit membaca papan tulis karena pantulan cahaya jendela","Semua siswa di sekolah ini harus berusaha lebih baik lagi dalam belajar dan bersikap setiap harinya","Dunia pendidikan di negara kita tidak adil bagi siswa yang tempat duduknya jauh dari papan tulis"],answer:0,explain:"Masalah yang bisa ditindaklanjuti bersifat spesifik, terbatas, dan menyebut penyebab yang mungkin diubah.",hint:"Mana yang bisa kamu mulai kerjakan besok pagi?"},
{n:51,type:"open",micro:"Menerapkan 5 Mengapa",q:"Terapkan teknik '5 Mengapa' pada masalah: 'Tanaman di pot kelas mati.' Tuliskan minimal 3 lapis 'mengapa'.",explain:"Jawaban baik bergerak dari gejala terlihat menuju penyebab yang bisa diperbaiki, biasanya soal sistem atau kebiasaan.",hint:"Tiap jawaban 'karena...' jadi bahan pertanyaan berikutnya.",sample:"1) Mengapa mati? Karena daunnya kering total. 2) Mengapa kering? Karena tidak disiram beberapa hari. 3) Mengapa tidak disiram? Karena tidak ada jadwal siapa yang menyiram. 4) Mengapa tidak ada jadwal? Karena tidak ada yang ditugaskan saat pot dibeli. Akar: tidak ada penanggung jawab yang ditetapkan."},
{n:52,type:"mcq",micro:"Membedakan masalah dari keputusan",q:"'Haruskah aku ikut klub musik atau klub sains?' Ini lebih tepat disebut...",options:["Sebuah masalah, karena ada hambatan jelas yang harus segera dihilangkan darimu","Sebuah keputusan/pilihan antara beberapa opsi yang sama-sama mungkin","Bukan masalah maupun keputusan, karena memilih klub tidak butuh pertimbangan"],answer:1,explain:"Masalah punya hambatan yang menghalangi tujuan; keputusan adalah memilih di antara beberapa jalan yang terbuka.",hint:"Apakah ada yang menghalangimu, atau kamu hanya perlu memilih?"},
{n:53,type:"mcq",micro:"Masalah terdefinisi baik vs buruk",q:"Masalah 'terdefinisi baik' (well-defined) memiliki...",options:["Tujuan yang kabur dan aturan yang tidak ditentukan, sehingga tiap orang menafsirkannya sendiri","Jawaban yang tidak mungkin ditemukan, sehingga masalah seperti itu sebaiknya ditinggalkan","Keadaan awal, tujuan, dan batasan yang jelas — seperti teka-teki dengan aturan pasti"],answer:2,explain:"Masalah terdefinisi baik: jelas titik awal, titik tujuan, dan aturannya (contoh: menyelesaikan labirin). Masalah terdefinisi buruk lebih kabur (contoh: 'membuat sekolah menyenangkan').",hint:"Apakah semua orang sepakat seperti apa 'selesai' itu?"},
{n:54,type:"mcq",micro:"Menangani masalah terdefinisi buruk",q:"Saat menghadapi masalah yang kabur seperti 'siswa kurang semangat belajar', langkah awal yang paling membantu adalah...",options:["Memecahnya menjadi bagian yang lebih spesifik dan bisa diamati, lalu memilih satu untuk digarap dulu","Langsung membuat aturan baru yang berlaku untuk seluruh siswa tanpa mengamati apa yang terjadi","Menyerah saja karena masalah yang kabur terlalu sulit dipahami dan diselesaikan oleh pihak sekolah"],answer:0,explain:"Masalah kabur menjadi bisa dikerjakan setelah dipersempit menjadi bagian konkret yang terukur.",hint:"Bagian 'kurang semangat' yang mana yang bisa kamu lihat dan hitung?"},
{n:55,type:"mcq",micro:"Reframing / membingkai ulang",q:"'Membingkai ulang' sebuah masalah berarti...",options:["Mengabaikan masalah itu dulu sampai keadaannya menjadi tenang dengan sendirinya","Melihat masalah yang sama dari sudut pandang berbeda sehingga muncul solusi baru","Membuat masalah tampak lebih besar supaya orang lain mau ikut membantu menyelesaikannya"],answer:1,explain:"Contoh: 'antrean lift terlalu panjang' dibingkai ulang menjadi 'waktu menunggu terasa lama' — solusinya bisa cermin di dekat lift, bukan lift baru.",hint:"Kadang mengubah pertanyaannya membuka pintu jawaban yang berbeda."},
{n:56,type:"mcq",micro:"Sebab vs akibat",q:"'Nilai kelas rendah DAN siswa jarang bertanya.' Kesalahan berpikir yang umum di sini adalah...",options:["Tidak ada kesalahan berpikir di sini, karena dua hal yang muncul bersamaan memang saling menyebabkan satu sama lain","Menganggap keduanya tidak berhubungan, padahal nilai dan keberanian bertanya bisa saling memengaruhi","Langsung yakin bahwa jarang bertanya PASTI penyebab nilai rendah, padahal keduanya bisa disebabkan hal ketiga"],answer:2,explain:"Dua hal yang muncul bersamaan belum tentu yang satu menyebabkan yang lain; bisa jadi ada penyebab bersama, misalnya materi terlalu cepat.",hint:"Apakah A menyebabkan B, B menyebabkan A, atau C menyebabkan keduanya?"},
{n:57,type:"tf",micro:"Definisi masalah memengaruhi solusi",q:"Benar atau Salah: Cara kita mendefinisikan masalah hampir tidak berpengaruh pada solusi yang akhirnya kita temukan.",answer:false,explain:"Justru sangat berpengaruh. 'Jalanan macet' mengarah ke pelebaran jalan; 'terlalu banyak mobil pribadi' mengarah ke transportasi umum. Definisi menentukan arah solusi.",hint:"Kalau kamu salah menyebut masalahnya, ke mana solusimu akan menuju?"},
{n:58,type:"mcq",micro:"Memisahkan fakta, tafsiran, dan penilaian",q:"'Dia datang terlambat 15 menit (fakta). Dia pasti tidak menghargai kita (tafsiran). Itu perbuatan yang buruk (penilaian).' Untuk mendefinisikan masalah, kita harus mulai dari...",options:["Fakta","Penilaian","Tafsiran"],answer:0,explain:"Fakta adalah dasar yang bisa diperiksa bersama; tafsiran dan penilaian datang belakangan dan harus diuji.",hint:"Mana yang bisa disepakati semua orang tanpa berdebat?"},
{n:59,type:"mcq",micro:"Masalah yang layak diselesaikan",q:"Sebelum menghabiskan banyak waktu, pertanyaan penting tentang sebuah masalah adalah...",options:["Apakah orang lain juga punya masalah yang sama persis dengan masalah yang sedang kita hadapi?","Apakah masalah ini cukup penting dan sering, dan apakah kita punya pengaruh untuk mengubahnya?","Apakah masalah ini terdengar keren dan membuat orang lain kagum ketika kita ceritakan nanti?"],answer:1,explain:"Prioritaskan masalah yang berdampak besar DAN berada dalam jangkauan pengaruh kita.",hint:"Penting + bisa kita pengaruhi = layak digarap."},
{n:60,type:"open",micro:"Merumuskan masalah lengkap",q:"Gunakan kerangka 'Saat ini ..., padahal ..., karena ..., sehingga ...' untuk merumuskan masalah tentang sampah di kelasmu.",explain:"Rumusan lengkap menyebut keadaan sekarang, keadaan ideal, hambatan/sebab, dan dampak.",hint:"Isi keempat bagian kerangka satu per satu.",sample:"Contoh: 'Saat ini tempat sampah kelas selalu penuh sebelum siang, padahal seharusnya cukup menampung sampah satu hari, karena hanya ada satu tempat sampah kecil dan tidak ada pemilahan, sehingga sampah tercecer di lantai dan kelas jadi kotor.'"},
{n:61,type:"mcq",micro:"Masalah yang sebenarnya",q:"Warga mengeluh 'lampu jalan kurang terang'. Setelah diperiksa, ternyata lampu cukup terang tetapi banyak tertutup ranting pohon. Masalah sebenarnya adalah...",options:["Lampu jalan memang tidak ada, sehingga warga mengeluh jalannya terlalu gelap","Lampu terlalu redup dan seluruhnya harus diganti dengan yang lebih terang","Ranting pohon menghalangi cahaya lampu yang sebenarnya sudah cukup"],answer:2,explain:"Menyelidiki dulu mencegah kita 'menyelesaikan' masalah yang salah (mengganti lampu) alih-alih yang benar (memangkas ranting).",hint:"Apa yang berubah setelah diperiksa langsung di lapangan?"},
{n:62,type:"mcq",micro:"Masalah milik siapa",q:"Kakak stres karena ujiannya, lalu jadi mudah marah ke kamu. Kamu ingin suasana rumah tenang. Masalah 'stres ujian' itu milik siapa, dan masalah 'suasana rumah tegang' milik siapa?",options:["Stres ujian milik kakak; suasana rumah tegang adalah masalah bersama yang juga milikmu","Keduanya milikmu, karena kamu yang merasakan akibat kakak sedang stres belajar","Keduanya milik kakak, karena kakaklah yang menyebabkan stres dan suasana tegang"],answer:0,explain:"Memilah kepemilikan masalah membantu memilih tindakan: kamu tidak bisa mengerjakan ujian kakak, tapi kamu bisa ikut menjaga suasana rumah.",hint:"Masalah mana yang berada dalam kendalimu untuk memengaruhi?"},
{n:63,type:"mcq",micro:"Bingkai yang salah",q:"Sebuah toko berpikir masalahnya 'pesaing menjual lebih murah', lalu ikut membanting harga sampai rugi. Kemungkinan bingkai yang lebih baik:",options:["'Bagaimana membanting harga lebih rendah lagi dari pesaing, berapa pun kerugian yang harus ditanggung toko?'","'Bagaimana memberi nilai lebih (layanan, kualitas, kedekatan) sehingga harga bukan satu-satunya alasan orang membeli?'","'Bagaimana menutup toko secepatnya supaya pemilik tidak perlu lagi memikirkan pesaing yang ada?'"],answer:1,explain:"Membingkai masalah hanya sebagai 'perang harga' mempersempit solusi ke satu jalan yang merugikan. Bingkai lain membuka pilihan.",hint:"Apakah harga benar-benar satu-satunya alasan orang memilih sebuah toko?"},
{n:64,type:"tf",micro:"Definisi sempit menyembunyikan pola",q:"Benar atau Salah: Jika tiga kelas berbeda melaporkan proyektor rusak di minggu yang sama, cara terbaik selalu menangani tiap laporan sebagai masalah yang benar-benar terpisah tanpa perlu mencari penyebab bersama.",answer:false,explain:"Beberapa kejadian serupa dalam waktu berdekatan sering menandakan satu penyebab sistemik (misalnya tegangan listrik atau batch alat yang cacat). Menanganinya terpisah-pisah bisa membuat kita melewatkan akar yang sama.",hint:"Tiga kejadian mirip sekaligus — kebetulan, atau ada benang merah?"},
{n:65,type:"mcq",micro:"Definisi terlalu luas",q:"Mendefinisikan masalah sebagai 'sistem pendidikan kita bermasalah' saat kamu hanya ingin memperbaiki perpustakaan kelas berisiko...",options:["Tidak berisiko, karena makin luas definisi masalahnya maka makin cepat masalah itu selesai","Langsung menyelesaikan masalah perpustakaan kelas karena masalah pendidikan ikut terselesaikan","Membuat masalah terasa terlalu besar untuk ditangani sehingga tidak ada tindakan yang dimulai"],answer:2,explain:"Definisi yang terlalu luas melumpuhkan tindakan. Persempit ke bagian yang benar-benar ingin dan bisa kamu ubah.",hint:"Apakah kamu bisa memperbaiki 'seluruh sistem' sendirian minggu ini?"},
{n:66,type:"mcq",micro:"Bias konfirmasi saat mengenali masalah",q:"Kamu sudah yakin 'aplikasi ini lemot karena HP-ku jelek'. Kamu hanya memperhatikan saat aplikasi lambat dan mengabaikan saat cepat. Ini contoh...",options:["Bias konfirmasi — hanya mencatat bukti yang cocok dengan keyakinan awal","Bias penyintas — hanya melihat contoh yang berhasil dan melupakan yang gagal","Efek placebo — merasa lebih baik hanya karena percaya HP-nya akan membaik"],answer:0,explain:"Bias konfirmasi membuat kita salah menilai masalah. Catat juga kejadian yang tidak sesuai dugaan.",hint:"Apakah kamu mencatat semua kejadian, atau hanya yang mendukung tebakanmu?"},
{n:67,type:"mcq",micro:"Masalah vs kesulitan yang wajar",q:"Belajar bersepeda terasa sulit dan sering jatuh di minggu pertama. Apakah 'sering jatuh' itu masalah yang harus 'diperbaiki' segera?",options:["Ya, berarti ada yang sangat salah pada dirimu, sehingga kamu harus segera diperbaiki oleh orang dewasa","Tidak selalu — jatuh beberapa kali adalah bagian wajar dari proses belajar; ini kesulitan, bukan tanda kegagalan","Ya, sebaiknya kamu berhenti belajar bersepeda saja karena jatuh berarti kamu memang tidak berbakat"],answer:1,explain:"Tidak semua kesulitan adalah masalah yang perlu dipecahkan. Sebagian adalah bagian normal dari belajar dan berkembang.",hint:"Apakah kesulitan ini menghalangi kemajuan, atau justru bagian dari kemajuan itu?"},
{n:68,type:"mcq",micro:"Menantang definisi awal",q:"Tim memutuskan masalahnya adalah 'kita butuh aplikasi baru'. Pertanyaan penantang yang sehat:",options:["'Warna apa yang paling bagus untuk logo aplikasi baru kita nanti, supaya terlihat menarik bagi pengguna?'","'Siapa yang mau membuat aplikasinya, dan berapa lama waktu yang dibutuhkan sampai aplikasinya selesai dibuat?'","'Masalah pengguna apa sebenarnya yang ingin kita selesaikan, dan apakah aplikasi satu-satunya cara?'"],answer:2,explain:"'Kita butuh solusi X' sering menyamar sebagai definisi masalah. Kembalikan ke masalah pengguna yang sebenarnya.",hint:"Sebuah solusi yang sudah dipilih bukanlah definisi masalah."},
{n:69,type:"mcq",micro:"Data bertentangan dengan cerita",q:"Semua orang bilang 'kantin selalu penuh saat istirahat kedua'. Tapi catatan selama 2 minggu menunjukkan istirahat PERTAMA yang paling padat. Sebaiknya kamu...",options:["Percayai data yang tercatat dan definisikan ulang kapan masalah kepadatan benar-benar terjadi","Anggap masalah kepadatan tidak ada, karena catatan dua minggu itu kemungkinan keliru dicatat","Abaikan data yang tercatat dan ikuti pendapat mayoritas, karena suara terbanyak lebih benar"],answer:0,explain:"Ketika data yang dikumpulkan dengan hati-hati bertentangan dengan anggapan umum, definisi masalah perlu diperbarui mengikuti bukti.",hint:"Mana yang lebih bisa dipercaya: ingatan orang atau catatan selama dua minggu?"},
{n:70,type:"order",micro:"Menguji apakah definisi masalah sudah tepat",q:"Urutkan langkah untuk memeriksa apakah definisimu tentang sebuah masalah sudah tepat.",items:["Tuliskan definisi awal masalah","Kumpulkan bukti langsung: amati, hitung, tanya orang yang terdampak","Bandingkan bukti dengan definisi awal, lalu perbaiki definisinya bila perlu"],answer:[0,1,2],explain:"Definisi awal adalah hipotesis; bukti mengujinya; lalu kita revisi. Ini siklus, bukan sekali jalan.",hint:"Kamu butuh sesuatu untuk diuji sebelum bisa mengujinya."},
{n:71,type:"mcq",micro:"Masalah simetris: dua pihak",q:"Dua kelas berebut memakai aula pada jam yang sama. Definisi masalah yang paling membantu:",options:["'Kelas sebelah egois dan sengaja mau menang sendiri, sehingga mereka harus ditegur supaya mengalah'","'Dua kelas membutuhkan aula pada slot waktu yang sama, sedangkan aula hanya bisa dipakai satu kelas sekaligus'","'Aula terlalu kecil dan sempit, sehingga harus segera diganti dengan aula baru yang jauh lebih besar'"],answer:1,explain:"Definisi netral yang menyebut kebutuhan kedua pihak dan batasan sumber daya membuka jalan ke solusi bersama (jadwal bergilir).",hint:"Sebutkan kebutuhan kedua pihak tanpa menyalahkan."},
{n:72,type:"tf",micro:"Gejala mendesak vs akar penting",q:"Benar atau Salah: Kadang kita perlu meredakan gejala yang mendesak lebih dulu (misalnya mengepel lantai licin) sambil tetap merencanakan perbaikan akar masalah (pipa bocor).",answer:true,explain:"Menangani gejala mendesak untuk keselamatan itu wajar, asal kita tidak berhenti di situ dan lupa akar masalahnya.",hint:"Apakah menunda mengepel sampai pipa diperbaiki itu aman?"},
{n:73,type:"mcq",micro:"Masalah yang berubah seiring waktu",q:"Tahun lalu masalah klub adalah 'anggota terlalu sedikit'. Sekarang anggota banyak tapi 'kegiatan tidak terorganisir'. Ini menunjukkan...",options:["Masalah lama dan masalah baru itu sama, sehingga definisi lama tidak perlu ditinjau","Klub itu tidak akan beres, karena tiap masalah yang selesai diganti masalah lain","Masalah bisa berevolusi; definisi lama perlu ditinjau ulang secara berkala"],answer:2,explain:"Setelah satu masalah teratasi, masalah baru sering muncul. Peninjauan berkala menjaga fokus tetap pada masalah yang relevan sekarang.",hint:"Apakah masalah hari ini sama dengan masalah tahun lalu?"},
{n:74,type:"mcq",micro:"Salah menempatkan penyebab pada orang",q:"'Pelanggan sering salah mengisi formulir' bisa didefinisikan sebagai 'pelanggan ceroboh' ATAU 'formulir membingungkan'. Definisi kedua lebih berguna karena...",options:["Mengarah ke perbaikan yang bisa kita kendalikan (memperjelas formulir) daripada menyalahkan pihak yang tak bisa kita ubah","Lebih jujur karena langsung menyebut pihak yang salah, sehingga mereka bisa segera ditegur dan malu di depan umum","Lebih singkat dan lebih mudah diingat, sehingga pembaca cepat setuju tanpa perlu memikirkan penyebab lainnya"],answer:0,explain:"Bila banyak orang berbeda membuat kesalahan yang sama, penyebabnya lebih mungkin pada rancangan, bukan pada tiap individu.",hint:"Kalau 9 dari 10 orang tersandung di anak tangga yang sama, salah siapa?"},
{n:75,type:"mcq",micro:"Memisahkan masalah dari solusi favorit",q:"Seseorang berkata: 'Masalahnya adalah kita tidak punya lapangan basket baru.' Ini bermasalah sebagai definisi karena...",options:["Lapangan basket memang tidak penting bagi siswa, sehingga masalah itu tidak perlu ditanggapi serius","Itu sudah melompat ke satu solusi; masalah aslinya mungkin 'siswa kurang tempat berolahraga saat istirahat'","Definisi itu sudah sempurna dan jelas, karena langsung menyebutkan apa yang harus dibeli oleh sekolah"],answer:1,explain:"Menyamakan masalah dengan satu solusi menutup pilihan lain (memperbaiki lapangan lama, menjadwal ulang, olahraga jenis lain).",hint:"Apa kebutuhan di balik keinginan 'lapangan baru'?"},
{n:76,type:"mcq",micro:"Skala dan prioritas",q:"Kamu menemukan 5 masalah di kelas. Cara masuk akal memilih mana yang digarap dulu:",options:["Garap kelima masalah itu sekaligus pada waktu yang sama, tanpa perlu membandingkan yang lebih penting","Pilih masalah yang paling mudah diucapkan atau paling enak didengar, tanpa memikirkan dampaknya bagi kelas","Nilai tiap masalah dari seberapa sering terjadi, seberapa besar dampaknya, dan seberapa mampu kamu memengaruhinya"],answer:2,explain:"Prioritas yang baik mempertimbangkan frekuensi, dampak, dan kendali/pengaruh yang kita miliki.",hint:"Mana yang memberi perbaikan terbesar dengan usaha yang realistis?"},
{n:77,type:"tf",micro:"Bertanya ke orang terdampak",q:"Benar atau Salah: Saat mendefinisikan masalah yang memengaruhi orang lain, menanyakan langsung pengalaman mereka biasanya memberi gambaran yang lebih akurat daripada menebak sendiri.",answer:true,explain:"Orang yang mengalami masalah punya informasi yang tidak terlihat dari luar. Bertanya mengurangi risiko salah bingkai.",hint:"Siapa yang paling tahu bagaimana rasanya mengantre 20 menit setiap hari?"},
{n:78,type:"mcq",micro:"Masalah palsu dari perbandingan",q:"'Sekolah lain punya kolam renang, kita tidak — itu masalah besar kita.' Kelemahan cara berpikir ini:",options:["Menjadikan 'berbeda dari orang lain' otomatis sebagai masalah, tanpa memeriksa apakah itu benar-benar menghambat tujuan sekolah","Kolam renang termasuk fasilitas wajib bagi sekolah, sehingga ketiadaannya jelas menjadi masalah besar bagi sekolah kita","Cara berpikir ini sudah benar dan lengkap, sehingga tidak ada kelemahan yang perlu diperbaiki oleh pihak sekolah"],answer:0,explain:"Tidak memiliki sesuatu yang dimiliki orang lain belum tentu masalah, kecuali hal itu menghalangi tujuan yang kita anggap penting.",hint:"Apakah ketiadaan kolam renang menghalangi tujuan belajar di sekolah ini?"},
{n:79,type:"mcq",micro:"Menyatukan gejala menjadi satu masalah",q:"Gejala: perpustakaan sepi, buku baru jarang dibaca, siswa bilang 'tidak tahu ada buku itu'. Definisi masalah yang menyatukan ketiganya:",options:["Siswa memang tidak suka membaca, jadi perpustakaan tidak diminati para siswa","Informasi tentang koleksi dan kegiatan perpustakaan tidak sampai ke siswa","Perpustakaan harus dibongkar dan dibangun ulang supaya terlihat lebih modern"],answer:1,explain:"Definisi yang baik menjelaskan sebanyak mungkin gejala dengan satu akar yang masuk akal — di sini, masalah komunikasi/kesadaran.",hint:"Akar mana yang bisa menjelaskan ketiga gejala sekaligus?"},
{n:80,type:"open",micro:"Membingkai ulang sebuah masalah",q:"Masalah awal: 'Antrean cuci tangan di wastafel kelas terlalu panjang sebelum makan.' Tuliskan dua cara berbeda membingkai ulang masalah ini, dan bagaimana tiap bingkai mengarah ke solusi yang berbeda.",explain:"Membingkai ulang mengubah letak 'penyebab', dan tiap letak penyebab membuka jenis solusi yang berbeda.",hint:"Ubah bagian 'karena ...' dalam rumusan masalah, lalu lihat solusi apa yang muncul.",sample:"Bingkai 1: 'Terlalu sedikit titik cuci tangan.' → solusi: tambah wastafel portabel / ember keran. Bingkai 2: 'Semua siswa mencoba cuci tangan pada menit yang sama.' → solusi: jadwalkan cuci tangan bergiliran per baris, atau mulai 5 menit lebih awal. Bingkai 3 (opsional): 'Proses cuci tangan tiap anak terlalu lama.' → solusi: sediakan sabun cair yang lebih cepat, tempel poster langkah 20 detik."},
{n:81,type:"mcq",micro:"Menyaring masalah inti dari cerita panjang",q:"'Aku bangun telat karena begadang nonton, lalu ketinggalan bus, jajan sembarangan di jalan jadi sakit perut, dan akhirnya tidak fokus ulangan.' Jika kamu hanya boleh menangani SATU akar, mana yang paling berpengaruh ke seluruh rantai?",options:["Rasa tidak fokus saat mengerjakan soal ulangan di kelas","Sakit perut akibat jajan sembarangan di jalan menuju sekolah","Kebiasaan begadang menonton di malam sebelum hari penting"],answer:2,explain:"Begadang adalah simpul paling awal; memperbaikinya kemungkinan besar memutus sebagian besar rantai masalah berikutnya.",hint:"Cari kejadian paling awal yang memicu kejadian-kejadian lain."},
{n:82,type:"mcq",micro:"Masalah sistem vs masalah orang",q:"Di sebuah dapur restoran, 5 koki berbeda secara bergantian membuat kesalahan pesanan yang sama pada menu tertentu. Definisi masalah terbaik:",options:["Ada yang membingungkan pada cara menu itu ditulis atau disiapkan, sehingga orang yang berbeda pun keliru dengan pola yang sama","Menu itu sebaiknya dihapus saja dari daftar tanpa diselidiki lagi, sehingga kesalahan pesanan tidak akan terjadi lagi di dapur","Kelima koki itu sama-sama kurang teliti dan malas, sehingga mereka semua perlu ditegur dan diberi hukuman bersama-sama"],answer:0,explain:"Kesalahan berpola yang dibuat banyak orang berbeda menunjuk ke rancangan proses, bukan ke sifat tiap individu.",hint:"Kalau orangnya berganti-ganti tapi kesalahannya sama, apa yang tetap sama?"},
{n:83,type:"tf",micro:"Definisi masalah dan keadilan",q:"Benar atau Salah: Rumusan sebuah masalah selalu bersifat netral, jadi tidak mungkin membuat kelompok yang justru paling dirugikan malah tampak sebagai penyebabnya.",answer:false,explain:"Rumusan tidak selalu netral. Contoh: 'siswa daerah jauh sering terlambat' membingkai mereka sebagai penyebab, padahal akar sebenarnya mungkin tidak adanya transportasi. Definisi yang adil melihat konteks.",hint:"Siapa yang terdengar 'bersalah' dalam definisi itu, dan apakah itu adil?"},
{n:84,type:"mcq",micro:"Masalah dengan tujuan yang bertentangan",q:"OSIS ingin acara sekolah yang meriah (butuh dana besar), tapi juga ingin tiket murah agar semua bisa ikut. Ini adalah...",options:["Bukan masalah, cukup pilih salah satu tujuan saja dan abaikan tujuan yang lain sepenuhnya begitu saja","Masalah dengan dua tujuan yang saling menekan; definisinya harus mengakui keduanya dan mencari titik seimbang","Masalah yang tak mungkin dipikirkan, karena dua tujuan yang bertentangan tidak bisa diseimbangkan"],answer:1,explain:"Banyak masalah nyata melibatkan tujuan yang bersaing. Definisi yang jujur menyebut kedua tujuan dan batasannya, lalu mencari kompromi atau kreativitas.",hint:"Bisakah definisi masalah menampung 'meriah' DAN 'terjangkau' sekaligus?"},
{n:85,type:"mcq",micro:"Kapan berhenti mendefinisikan dan mulai bertindak",q:"Sebuah tim sudah 3 pertemuan hanya berdebat soal rumusan masalah dan belum melakukan apa pun. Nasihat yang seimbang:",options:["Batalkan proyeknya dan bentuk tim baru yang anggotanya dipilih dari orang-orang yang mudah sepakat satu sama lain","Teruskan berdebat sampai rumusan masalahnya benar-benar sempurna dan semua anggota tim setuju sepenuhnya","Kunci definisi 'cukup baik' untuk sekarang, mulai langkah kecil, dan perbaiki definisi sambil belajar dari hasilnya"],answer:2,explain:"Definisi masalah tidak harus sempurna sebelum bertindak. Tindakan kecil sering memberi informasi yang menyempurnakan definisi.",hint:"Kesempurnaan definisi vs kehilangan waktu — di mana keseimbangannya?"},
{n:86,type:"mcq",micro:"Masalah tersembunyi di balik solusi yang diminta",q:"Seorang siswa berkata ke guru: 'Bu, boleh saya pindah tempat duduk ke depan?' Kemungkinan masalah tersembunyi yang perlu digali guru:",options:["Bisa jadi ada masalah penglihatan, kesulitan fokus, atau masalah dengan teman sebangku — permintaan itu mungkin gejala","Siswa itu hanya ingin mencari perhatian guru dan teman-temannya, jadi permintaannya tidak perlu ditanggapi","Tidak ada masalah tersembunyi di balik permintaan itu, jadi guru cukup mengabulkan atau menolaknya saja"],answer:0,explain:"Permintaan solusi spesifik sering menyembunyikan masalah yang belum diungkapkan. Bertanya 'kenapa' dengan ramah membukanya.",hint:"Apa yang mungkin mendorong permintaan ini?"},
{n:87,type:"order",micro:"Alur menghadapi situasi berantakan",q:"Urutkan langkah menghadapi situasi yang penuh keluhan campur aduk.",items:["Kumpulkan semua keluhan dan gejala yang disebutkan","Kelompokkan gejala yang mirip dan cari kemungkinan akar bersama","Rumuskan 1–2 pernyataan masalah yang jelas dan bisa ditindaklanjuti","Pilih satu masalah untuk digarap lebih dulu berdasarkan dampak dan pengaruh"],answer:[0,1,2,3],explain:"Dari mengumpulkan, mengelompokkan, merumuskan, hingga memprioritaskan — ini alur mengubah kekacauan menjadi fokus.",hint:"Kamu harus melihat semuanya dulu sebelum bisa mengelompokkan dan memilih."},
{n:88,type:"mcq",micro:"Membedakan masalah dari risiko",q:"'Server kita BELUM pernah down, tapi kalau listrik mati saat ujian daring, semua nilai bisa hilang.' Ini lebih tepat disebut...",options:["Masalah yang sedang terjadi saat ini, sehingga harus diperbaiki seperti masalah yang sudah muncul","Sebuah risiko — masalah yang belum terjadi tapi mungkin terjadi dan layak diantisipasi","Bukan apa-apa dan tidak perlu dipikirkan, karena kejadian yang belum terjadi tidak membahayakan"],answer:1,explain:"Risiko adalah masalah potensial. Mengenalinya lebih awal memungkinkan pencegahan (cadangan daya, penyimpanan otomatis).",hint:"Sudah terjadi, atau baru berpotensi terjadi?"},
{n:89,type:"mcq",micro:"Definisi masalah yang bisa diukur",q:"Manakah definisi masalah yang paling mudah dipantau kemajuannya?",options:["'Perpustakaan sekolah kita kurang hidup dan kurang menarik bagi sebagian besar siswa kelas 5 saat ini'","'Semangat baca siswa di sekolah ini rendah sekali, terutama dibanding sekolah-sekolah lain di sekitar kita'","'Rata-rata siswa kelas 5 meminjam 0,5 buku per bulan dari perpustakaan sekolah; target wajar sekolah adalah 2 buku per bulan'"],answer:2,explain:"Definisi dengan angka dan target memungkinkan kita mengukur apakah keadaan membaik setelah solusi diterapkan.",hint:"Mana yang bisa kamu cek lagi bulan depan dengan angka?"},
{n:90,type:"tf",micro:"Satu gejala, banyak kemungkinan masalah",q:"Benar atau Salah: Gejala 'HP cepat panas' selalu berasal dari satu penyebab yang sama, sehingga begitu kita melihat gejalanya kita bisa langsung memilih solusinya.",answer:false,explain:"Panas bisa karena aplikasi berat, baterai tua, casing tebal, atau cuaca. Perlu penyelidikan untuk menentukan masalah spesifik sebelum memilih solusi.",hint:"Apakah satu solusi cocok untuk semua kemungkinan penyebab panas?"},
{n:91,type:"mcq",micro:"Menghindari solusi yang memindahkan masalah",q:"Untuk mengatasi 'koridor lantai 1 ramai dan sesak saat pergantian jam', sekolah memajukan bel lantai 1 lima menit. Hasilnya koridor lantai 2 jadi sesak. Ini menunjukkan...",options:["Definisi masalah terlalu sempit — masalah sebenarnya adalah alur perpindahan seluruh sekolah, bukan hanya lantai 1","Sekolah sudah tidak bisa berbuat lagi, karena upaya yang dicoba hanya akan memindahkan masalah ke lantai lain","Masalah sudah selesai total, karena lantai 1 sekarang lebih lengang dan lantai lain tidak perlu diperhatikan"],answer:0,explain:"Ketika solusi hanya memindahkan masalah ke tempat lain, biasanya masalah didefinisikan terlalu lokal.",hint:"Apakah masalahnya benar-benar 'lantai 1', atau lebih luas?"},
{n:92,type:"mcq",micro:"Peran asumsi tak terucap",q:"Tim yakin masalahnya 'aplikasi terlalu lambat', dan asumsi tak terucapnya adalah 'pengguna kita punya internet cepat'. Kalau ternyata banyak pengguna pakai internet lambat...",options:["Asumsi itu tidak penting, jadi tim cukup terus mempercepat aplikasinya tanpa memeriksa pengguna","Definisi masalah bisa keliru arah; mungkin masalahnya adalah aplikasi tidak dirancang untuk koneksi lambat","Aplikasi itu sebaiknya dihapus dari toko aplikasi karena penggunanya tidak akan menyukainya lagi"],answer:1,explain:"Asumsi yang tidak diperiksa bisa menyembunyikan bagian penting dari masalah. Menuliskan asumsi membantu mengujinya.",hint:"Apa yang tim anggap 'sudah pasti benar' tanpa mengeceknya?"},
{n:93,type:"mcq",micro:"Masalah kolektif vs individu",q:"Satu siswa kesulitan memahami pecahan → mungkin masalah belajar individu. Dua puluh lima dari 30 siswa di kelas yang sama kesulitan pecahan → lebih tepat didefinisikan sebagai...",options:["Bukan masalah karena sebagian besar siswa memang kesulitan memahami pecahan","Dua puluh lima masalah individu yang terpisah dan perlu ditangani satu per satu","Satu masalah tingkat kelas, mungkin terkait cara atau kecepatan materi disampaikan"],answer:2,explain:"Skala mengubah definisi: banyak orang dengan kesulitan yang sama pada waktu yang sama menunjuk ke penyebab bersama.",hint:"Berapa proporsi yang terdampak, dan apa artinya soal penyebabnya?"},
{n:94,type:"open",micro:"Mendefinisikan masalah dunia nyata yang berantakan",q:"Di lingkunganmu, sampah plastik menumpuk di selokan dan menyebabkan genangan saat hujan. Warga saling menyalahkan. Tuliskan sebuah pernyataan masalah yang: (a) netral (tidak menyalahkan), (b) menyebut dampak, (c) cukup spesifik untuk ditindaklanjuti.",explain:"Pernyataan kuat: fakta yang bisa diperiksa, penyebab pada sistem/kebiasaan (bukan orang), dan dampak konkret.",hint:"Hindari kata 'malas' atau 'tidak peduli'; ganti dengan keadaan yang bisa diamati.",sample:"Contoh: 'Sampah plastik rumah tangga (terutama kantong dan kemasan) terkumpul di sepanjang 200 meter selokan RT 04 karena tidak ada jadwal pembersihan rutin dan titik pembuangan resmi terdekat berjarak 1 km. Akibatnya, saat hujan lebat, air meluap ke jalan dan 8 rumah terdampak genangan.' Netral, menyebut sebab yang bisa diubah, dan dampak yang terukur."},
{n:95,type:"mcq",micro:"Menguji definisi dengan pertanyaan 'lalu kenapa'",q:"Definisi: 'Perpustakaan tutup saat jam istirahat.' Uji: 'Lalu kenapa itu masalah?' Jawaban yang menunjukkan definisinya perlu diperdalam:",options:["'Karena satu-satunya waktu luang siswa untuk membaca adalah jam istirahat, sehingga banyak yang tidak pernah sempat ke perpustakaan.'","'Karena aku sendiri tidak suka kalau perpustakaan tutup, dan menurutku itu sangat menyebalkan serta tidak adil bagi kita semua.'","'Karena memang sudah begitu aturannya dari dulu, dan perpustakaan itu memang tutup setiap kali jam istirahat tiba di sekolah.'"],answer:0,explain:"Bertanya 'lalu kenapa itu masalah' memaksa kita menyatakan tujuan yang terhalang dan dampaknya — inti dari definisi yang baik.",hint:"Jawaban mana yang menyebut tujuan yang terhalang?"},
{n:96,type:"mcq",micro:"Membedakan keluhan, permintaan, dan masalah",q:"Pasangkan dengan benar: 'AC kelas berisik sekali' (A), 'Tolong matikan AC-nya' (B), 'Suara AC membuat siswa di barisan belakang tidak mendengar penjelasan guru' (C).",options:["A = permintaan solusi, B = pernyataan masalah, C = keluhan","A = keluhan, B = permintaan solusi, C = pernyataan masalah","A = pernyataan masalah, B = keluhan, C = permintaan solusi"],answer:1,explain:"Keluhan mengungkap ketidaknyamanan; permintaan melompat ke solusi; pernyataan masalah menjelaskan apa yang terhalang dan mengapa itu penting.",hint:"Mana yang menyebut tujuan yang terhalang (mendengar guru)?"},
{n:97,type:"tf",micro:"Definisi bersama mengurangi konflik",q:"Benar atau Salah: Ketika beberapa pihak yang berselisih berhasil menyepakati satu definisi masalah yang netral, biasanya lebih mudah bekerja sama mencari solusi.",answer:true,explain:"Definisi bersama memindahkan energi dari 'siapa yang salah' ke 'apa yang perlu kita perbaiki bersama'.",hint:"Apakah lebih mudah bekerja sama saat semua sepakat soal apa masalahnya?"},
{n:98,type:"mcq",micro:"Mengenali ketika 'masalah' sebenarnya kabar baik yang belum siap dikelola",q:"Sebuah kanal video kecil tiba-tiba viral; komentar membanjir dan kreator kewalahan membalas. 'Masalah'-nya paling tepat dibingkai sebagai...",options:["'Penonton baru yang datang itu mengganggu kami, sehingga kami perlu cara untuk mengusir mereka secepatnya'","'Video kami terlalu bagus sehingga itu buruk bagi kami, dan lebih baik kami berhenti membuat video lagi'","'Pertumbuhan cepat melampaui kapasitas kami mengelola interaksi; kami perlu cara baru menangani volume komentar'"],answer:2,explain:"Kadang masalah muncul dari keberhasilan. Membingkainya sebagai 'kapasitas belum menyesuaikan pertumbuhan' mengarah ke solusi konstruktif.",hint:"Apa yang berubah (pertumbuhan) dan kapasitas apa yang belum mengikuti?"},
{n:99,type:"mcq",micro:"Definisi masalah sebagai hipotesis",q:"Sikap paling sehat terhadap pernyataan masalah yang baru kamu tulis adalah...",options:["Menganggapnya hipotesis terbaik saat ini yang akan diuji dan diperbaiki dengan bukti","Menganggapnya tidak penting karena hanya tulisan awal, sehingga tidak perlu dibaca ulang","Menganggapnya kebenaran final yang tidak boleh diubah lagi, walaupun ada bukti baru"],answer:0,explain:"Definisi masalah adalah titik awal yang bisa diperbaiki, bukan keputusan yang mengunci. Ini menjaga kita tetap terbuka pada bukti baru.",hint:"Apakah tebakan pertama harus dipegang mati-matian?"},
{n:100,type:"open",micro:"Kapstone: dari kekacauan ke fokus",q:"Pilih satu situasi nyata yang mengganggumu di sekolah/rumah/lingkungan. Lakukan seluruh proses: (1) tuliskan gejala-gejala yang kamu amati, (2) pisahkan fakta dari asumsi, (3) gunakan 3 lapis 'mengapa' untuk mencari akar, (4) tulis satu pernyataan masalah netral dengan kerangka 'Saat ini..., padahal..., karena..., sehingga...', (5) sebutkan 2 kriteria keberhasilan dan 2 batasan.",explain:"Kapstone menggabungkan semua keterampilan fase A–D: mengamati, memisahkan fakta/asumsi, menggali akar, merumuskan secara netral dan terukur, serta menetapkan kriteria dan batasan.",hint:"Kerjakan kelima langkah berurutan; jangan lompat ke solusi — berhenti di rumusan masalah.",sample:"Contoh ringkas — Situasi: kelas selalu gaduh 10 menit pertama setelah istirahat. (1) Gejala: guru mengulang instruksi 3–4 kali; pelajaran mulai telat ~8 menit; beberapa siswa masih di luar. (2) Fakta: pelajaran mulai telat (tercatat 5 hari); Asumsi: 'siswa sengaja mengulur' (belum terbukti). (3) Mengapa gaduh? Banyak siswa baru masuk saat bel. Mengapa telat masuk? Antre wastafel + jajan. Mengapa antre panjang? Semua istirahat berakhir di menit yang sama & fasilitas terbatas. (4) 'Saat ini pelajaran setelah istirahat rata-rata mulai 8 menit terlambat, padahal seharusnya mulai tepat bel, karena arus siswa kembali ke kelas menumpuk di menit terakhir akibat antrean wastafel dan kantin, sehingga waktu belajar berkurang ~40 menit/minggu.' (5) Kriteria: pelajaran mulai maksimal 2 menit setelah bel; ≥90% siswa sudah di kelas saat bel. Batasan: tidak menambah durasi istirahat; tanpa biaya besar."},
];
